_respond(statusLine, body) {
  if (!this._outputStream) {
    return;
  }
  const response = lazy.MailStringUtils.stringToByteString(
    `HTTP/1.1 ${statusLine}\r\n` +
      "Content-Type: text/html; charset=utf-8\r\n" +
      "Content-Security-Policy: default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'sha256-IREggE8e7pWHduQVJzPyqoCVQ62B/ZgkFu3129qNUkM='\r\n" +
      "Cache-Control: no-store\r\n" +
      "Connection: close\r\n\r\n" +
      body
  );
  this._outputStream.write(response, response.length);

  // Cleanly close after the first response to ensure it's fully flushed.
  this._outputStream.close();
  this._outputStream = null;
},

/**
 * Use the completed response URL to attempt to finish the flow and
 *   respond accordingly.
 *
 * @param {text} url - Full URL text.
 * @param {object} connection
 */
_completeWithURL(url, connection) {
  if (!this._claimConnection(connection)) {
    return;
  }

  // If this will be treated as an error by onAuthorizationRecevied, show
  // the error page instead of the success page.
  const parsedUrl = new URL(url);
  if (this._oauth.checkResultURL(parsedUrl)) {
    lazy.OAuth2PageGenerator.generateSuccessPage()
      .then(pageSource => {
        this._respond("200 OK", pageSource);
      })
      .catch(error => log.error(error));
  } else {
    lazy.OAuth2PageGenerator.generateErrorPage()
      .then(pageSource => {
        this._respond("200 OK", pageSource);
      })
      .catch(error => log.error(error));
  }
  Services.tm.dispatchToMainThread(() => {
    // Focus return needs to happen first, before the window reference is
    // cleaned up.
    this._returnFocus();
    this._oauth.finishAuthorizationRequest();
    this._oauth.onAuthorizationReceived(url);
  });
},

/**
 * Respond indicating something was unexpected with the HTTP request.
 *
 * @param {object} connection
 */
_fail(connection) {
  if (!this._claimConnection(connection)) {
    return;
  }
  lazy.OAuth2PageGenerator.generateErrorPage()
    .then(pageSource => {
      this._respond("400 Bad Request", pageSource);
    })
    .catch(error => log.error(error));
  Services.tm.dispatchToMainThread(() => {
    this._returnFocus();
    this._oauth.finishAuthorizationRequest();
    this._oauth.onAuthorizationFailed(
      Cr.NS_ERROR_FAILURE,
      '{ "error": "authorization_failed" }',
      "authorization failed"
    );
  });
